        List<String> selected=r.containsKey("genes_use_file")?geneSubset(input(r,"genes_use_file",root)):r.containsKey("genes_use")?strings(r.get("genes_use")):null;var options=new SignacPeakLinks.Options(r.getOrDefault("method","pearson").equals("pearson")?SignacPeakLinks.Method.PEARSON:SignacPeakLinks.Method.SPARSE_SPEARMAN,(int)integer(r,"distance",500000,0,536870912),r.get("min_distance")==null?null:(int)integer(r,"min_distance",0,-536870912,536870912),(int)integer(r,"min_cells",10,0,2000000),(int)integer(r,"n_sample",200,2,1000000),number(r,"pvalue_cutoff",0.05,0,1),number(r,"score_cutoff",0.05,0,Double.MAX_VALUE),bool(r,"gene_id",false),selected,integer(r,"maximum_audit_work",2000000000L,1,10000000000000L));
        List<String> warnings=new ArrayList<>();warnings.add("PRECOMPUTED_SEQUENCE_STATISTICS: GC.percent and sequence.length are declared captured inputs; this workflow does not inspect a reference genome. Review their assembly and RegionStats provenance.");if(original.duplicateCoordinates()>0)warnings.add("INTEGER_DUPLICATE_COORDINATES_SUMMED: "+original.duplicateCoordinates()+" peak count duplicates were aggregated exactly; sparse zeros retained.");if(options.minDistance()!=null&&options.minDistance()>options.distance())warnings.add("SOURCE_DISTANCE_MATRIX_DIFFERENCE: min.distance exceeds distance. Original subtraction leaves negative entries that as.logical treats as true, selecting the outer difference rather than an empty conventional interval. Review both requested thresholds.");
