    private static void writeIds(Path path,List<String> values)throws IOException{try(var out=Files.newBufferedWriter(path,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){for(String value:values){out.write(value);out.write('\n');}}}
