    private static List<Map<String,Object>> stop(Process process){List<ProcessHandle> handles=new ArrayList<>(process.descendants().toList());Collections.reverse(handles);handles.add(process.toHandle());for(var handle:handles)handle.destroy();boolean interrupted=false;try{process.waitFor(2,TimeUnit.SECONDS);}catch(InterruptedException error){interrupted=true;}for(var handle:handles)if(handle.isAlive())handle.destroyForcibly();long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);while(handles.stream().anyMatch(ProcessHandle::isAlive)&&System.nanoTime()<deadline)try{Thread.sleep(50);}catch(InterruptedException error){interrupted=true;}if(interrupted)Thread.currentThread().interrupt();List<Map<String,Object>> states=new ArrayList<>();for(var handle:handles)states.add(Map.of("pid",handle.pid(),"alive_after_cleanup",handle.isAlive()));return states;}
