    private static String portablePath(String parent,String value)throws IOException{String path=value.replace('\\','/');if(!path.startsWith("/")&&!path.matches("^[A-Za-z]:/.*"))path=parent.replace('\\','/')+"/"+path;String prefix="";if(path.matches("^[A-Za-z]:/.*")){prefix=path.substring(0,2).toUpperCase(Locale.ROOT);path=path.substring(2);}if(!path.startsWith("/"))throw new IOException("Runtime binding parent must be absolute");Deque<String> parts=new ArrayDeque<>();for(String part:path.split("/"))if(!part.isEmpty()&&!part.equals(".")){if(part.equals("..")){if(parts.isEmpty())throw new IOException("Runtime path escapes its root");parts.removeLast();}else parts.addLast(part);}return prefix+"/"+String.join("/",parts);}
